create table catalogo_fracciones (activo boolean not null, en_oferta boolean, factor_descuento_kardex numeric(5,4) not null, oferta_porcentaje numeric(5,2), precio_oferta numeric(12,2), precio_venta numeric(12,2) not null, id uuid not null, producto_id uuid not null, nombre_fraccion varchar(50) not null, primary key (id), constraint uq_producto_fraccion unique (producto_id, factor_descuento_kardex));
