create table cms_ajustes (id smallint not null, identidad_propia boolean, tamano_base integer not null, web_ubigeo varchar(6), color_primario varchar(7) not null, color_secundario varchar(7) not null, web_ruc varchar(11), modo varchar(20) not null, web_telefono varchar(20), hero_kicker varchar(80), horario_sabado varchar(80), horario_semana varchar(80), materiales_kicker varchar(80), correo_soporte varchar(150), web_email varchar(150), web_nombre varchar(150), banner varchar(180), hero_titulo varchar(180), materiales_titulo varchar(180), facebook varchar(200), instagram varchar(200), linkedin varchar(200), web_razon_social varchar(200), youtube varchar(200), web_direccion varchar(300), hero_texto varchar(400), materiales_texto varchar(400), resumen varchar(500), colores_json TEXT, materiales_json TEXT, origen_empresa TEXT, texto_faq TEXT, texto_garantia TEXT, texto_privacidad TEXT, texto_terminos TEXT, primary key (id));
create table compra_adjuntos (created_at timestamp(6), tamano_bytes bigint, compra_id uuid not null, id uuid not null, subido_por uuid not null, tipo varchar(30) not null, content_type varchar(100), url_archivo varchar(500) not null, nombre_original varchar(255) not null, primary key (id));
create table compras (fecha_emision date not null, fecha_vencimiento_pago date, subtotal_neto numeric(12,2) not null, total numeric(12,2), total_igv numeric(12,2) not null, moneda varchar(5) not null check ((moneda in ('PEN','USD','EUR'))), created_at timestamp(6), fecha_anulacion timestamp(6), updated_at timestamp(6), anulado_por uuid, id uuid not null, proveedor_id uuid not null, sede_id uuid not null, user_id uuid not null, estado_compra varchar(20) not null check ((estado_compra in ('BORRADOR','RECIBIDA','ANULADA'))), numero_orden_compra varchar(20) unique, estado_pago varchar(30) not null check ((estado_pago in ('PENDIENTE','PAGADO_PARCIAL','PAGADO'))), estado_recepcion varchar(30) not null check ((estado_recepcion in ('PENDIENTE','RECIBIDO_PARCIAL','RECIBIDO'))), numero_factura_proveedor varchar(50), motivo_anulacion TEXT, observaciones TEXT, primary key (id));
create table concepto_cotizacion (activo boolean not null, orden integer not null, valor numeric(12,2) not null, id uuid not null, tipo varchar(20) not null check ((tipo in ('MONTO','PORCENTAJE'))), nombre varchar(80) not null, primary key (id));
create table configuracion_empresa (ubigeo varchar(6), id bigint not null, updated_at timestamp(6), ruc varchar(11), actualizado_por uuid, telefono varchar(20), email varchar(150), nombre_comercial varchar(150) not null, razon_social varchar(200), direccion_fiscal varchar(300), logo_url varchar(500), primary key (id));
