create table conversaciones_web (archivado boolean, marcado_no_leido boolean, no_leidos_cliente integer not null, no_leidos_equipo integer not null, cliente_escribe_hasta timestamp(6), created_at timestamp(6), equipo_escribe_hasta timestamp(6), ultimo_mensaje_at timestamp(6), cliente_id uuid, id uuid not null, estado varchar(20), telefono varchar(20), clave varchar(36) not null unique, dispositivo varchar(40), nombre varchar(120) not null, correo varchar(150) not null, empresa varchar(150), ultimo_texto varchar(180), primary key (id));
create table correlativos (ultimo bigint not null, updated_at timestamp(6), clave varchar(40) not null, primary key (clave));
create table cotizaciones (cantidad_piezas numeric(12,4), fecha_vigencia date not null, modificada boolean not null, movilidad_monto numeric(12,2), otros_monto numeric(12,2), subtotal_materiales numeric(12,2), total numeric(12,2), utilidad_monto numeric(12,2), utilidad_porcentaje numeric(6,2), created_at timestamp(6), contacto_ruc varchar(11), cliente_id uuid, id uuid not null, sede_id uuid not null, user_id uuid not null, venta_id uuid, canal varchar(20) check ((canal in ('INTERNO','WEB'))), contacto_telefono varchar(20), estado varchar(30) not null check ((estado in ('PENDIENTE','EMITIDA','ACEPTADA','RECHAZADA','NO_COMPRADO','VENCIDA','CONVERTIDA'))), distrito varchar(80), contacto_correo varchar(150), contacto_razon_social varchar(200), nota_cambio TEXT, observaciones TEXT, otros_detalle TEXT, primary key (id));
create table detalle_compra (cantidad numeric(12,4) not null, cantidad_recibida numeric(12,4), igv_linea numeric(12,2) not null, porcentaje_igv numeric(5,2), precio_unitario_con_igv numeric(12,2) not null, subtotal numeric(12,2) not null, valor_unitario_neto numeric(12,4) not null, almacen_id uuid not null, compra_id uuid not null, fraccion_id uuid, id uuid not null, producto_id uuid not null, primary key (id));
