create table detalle_preforma (cantidad numeric(12,4) not null, igv_linea numeric(12,2) not null, porcentaje_igv numeric(5,2), precio_unitario_con_igv numeric(12,2) not null, subtotal numeric(12,2) not null, valor_unitario_neto numeric(12,4) not null, fraccion_id uuid, id uuid not null, preforma_id uuid not null, producto_id uuid, servicio_id uuid, nota_cambio TEXT, primary key (id));
