create table finanzas_cuenta_metodos (cuenta_id uuid not null, metodo_pago varchar(20) not null check ((metodo_pago in ('EFECTIVO','YAPE','PLIN','SIP_AGORA','TARJETA','TRANSFERENCIA'))), primary key (cuenta_id, metodo_pago));
