create table finanzas_pagos_cxp (monto numeric(12,2) not null, created_at timestamp(6), fecha_pago timestamp(6) not null, cuenta_por_pagar_id uuid not null, id uuid not null, registrado_por uuid, metodo_pago varchar(20) not null check ((metodo_pago in ('EFECTIVO','YAPE','PLIN','SIP_AGORA','TARJETA','TRANSFERENCIA'))), referencia varchar(100), observaciones TEXT, primary key (id));
