create table ordenes_despacho (fecha_programada date, intentos_fallidos integer, latitud_entrega numeric(9,6), longitud_entrega numeric(9,6), created_at timestamp(6), fecha_asignacion timestamp(6), fecha_entrega timestamp(6), fecha_salida timestamp(6), updated_at timestamp(6), recibido_por_documento varchar(15), creado_por uuid, id uuid not null, movilidad_id uuid, responsable_id uuid, sede_id uuid not null, venta_id uuid not null, codigo_seguimiento varchar(20) unique, contacto_telefono varchar(20), estado varchar(30) not null check ((estado in ('PENDIENTE','EN_CAMINO','ENTREGADO','FALLIDO'))), evidencia_content_type varchar(100), contacto_nombre varchar(150), recibido_por_nombre varchar(150), direccion_entrega varchar(255) not null, evidencia_nombre_original varchar(255), motivo_fallo TEXT, observaciones TEXT, referencia_entrega varchar(255), url_evidencia_entrega varchar(255), primary key (id));
create table pagos_venta (monto numeric(12,2) not null, created_at timestamp(6), id uuid not null, venta_id uuid not null, metodo_pago varchar(30) not null check ((metodo_pago in ('EFECTIVO','YAPE','PLIN','SIP_AGORA','TARJETA','TRANSFERENCIA'))), referencia varchar(100), primary key (id));
