create table suscripciones_push (created_at timestamp(6), id uuid not null, usuario_id uuid not null, dispositivo varchar(80), auth varchar(200) not null, p256dh varchar(200) not null, endpoint varchar(500) not null unique, primary key (id));
create table tarifa_movilidad (activo boolean not null, precio_base numeric(12,2) not null, precio_unidad_extra numeric(12,2) not null, unidades_incluidas integer not null, id uuid not null, distrito varchar(80) not null unique, primary key (id));
create table turnos_caja (monto_final_declarado numeric(12,2), monto_inicial numeric(12,2) not null, total_reembolsos numeric(12,2), total_retiros_socios numeric(12,2), fecha_apertura timestamp(6), fecha_cierre timestamp(6), id uuid not null, sede_id uuid not null, user_id uuid not null, estado varchar(20) not null check ((estado in ('ABIERTO','CERRADO'))), observaciones TEXT, primary key (id));
create table users (activo boolean not null, sesion_version integer, totp_enabled boolean, created_at timestamp(6), ultimo_login timestamp(6), celular varchar(15), documento varchar(15), id uuid not null, role_id uuid not null, sede_id uuid not null, ultimo_ip varchar(45), nombre_usuario varchar(50) not null unique, apellido varchar(100) not null, nombre varchar(100) not null, totp_secret varchar(100), email varchar(150) not null unique, biografia varchar(500), foto text, password_hash varchar(255) not null, primary key (id));
create table vapid_claves (id smallint not null, privada varchar(200) not null, publica varchar(200) not null, primary key (id));
create table ventas (subtotal_neto numeric(12,2) not null, total numeric(12,2) not null, total_igv numeric(12,2) not null, created_at timestamp(6), canal_venta varchar(10) check ((canal_venta in ('LOCAL','ONLINE'))), cliente_id uuid, cotizacion_id uuid, id uuid not null, preforma_id uuid, sede_id uuid not null, turno_caja_id uuid, user_id uuid not null, ticket_registro varchar(20), tipo_comprobante varchar(20) not null check ((tipo_comprobante in ('BOLETA','FACTURA','TICKET'))), estado varchar(30) not null check ((estado in ('COMPLETADA','ANULADA'))), estado_sunat varchar(30) check ((estado_sunat in ('PENDIENTE','ACEPTADO','RECHAZADO','ANULADO'))), serie_correlativo varchar(50) unique, referencia_pedido_online varchar(100) unique, hash_cpe varchar(255), mensaje_sunat TEXT, primary key (id));
