create index idx_kardex_referencia on kardex_movimientos (referencia_id, tipo_referencia);
create index idx_productos_sku on productos (codigo_sku);
create index idx_productos_activo_categoria on productos (activo, categoria_id);
create index idx_stock_ajustes_fecha on stock_ajustes (created_at);
create index idx_stock_ajustes_producto on stock_ajustes (producto_id);
create index idx_stock_transferencias_fecha on stock_transferencias (created_at);
create index idx_ventas_estado_fecha on ventas (estado, created_at);
create index idx_ventas_sede_fecha on ventas (sede_id, created_at);
